/* ================= GASTOS ================= */
const G_CAT=['Alimentación','Hospedaje','Transporte','Movilidad local','Combustible','Representación','Capacitación','Otros'];
const NG={'Dirección':'g1','Gerencia':'g1','Jefatura':'g2','Supervisión':'g2','Especialista':'g3','Analista':'g3','Operativo':'g4'};
const GL={g1:'Dirección y gerencia',g2:'Jefatura y supervisión',g3:'Especialista y analista',g4:'Operativo'};
const G_EST={Borrador:'',Enviado:'warn',Aprobado:'acc',Rechazado:'crit',Pagado:'ok'};
const gas=id=>C('gastos').find(g=>g.id===id);
const nivelG=r=>NG[(get('puestos',r.puestoId)||{}).nivel]||'g3';
const tope=(r,cat)=>{const p=(P().gPol||{})[cat];return p?p[nivelG(r)]:null};
const enPEN=(m,mon)=>mon==='PEN'?m:(isNaN(par('tc_'+mon))?null:m*par('tc_'+mon));
const excede=(r,cat,m,mon)=>{const t=tope(r,cat),v=enPEN(Number(m),mon);return t!=null&&v!=null&&v>t};
const gHist=(g,t)=>{g.hist=g.hist||[];g.hist.unshift({f:now(),t,u:me().nombre})};
const gLab=g=>g.estado==='Enviado'?'Por aprobar: '+(g.etapa==='Jefe'?'jefe':'finanzas'):g.estado;
const canJefe=g=>{const mr=myRel(),r=rel(g.relId);return g.estado==='Enviado'&&g.etapa==='Jefe'&&!!mr&&!!r&&r.jefeId===mr.id&&can('gastos.aprobar.jefe')};
const canFin=g=>g.estado==='Enviado'&&g.etapa==='Finanzas'&&can('gastos.aprobar.finanzas')&&g.relId!==mrId();
const gPendMine=()=>C('gastos').filter(g=>canJefe(g)||canFin(g));
const rendOf=id=>C('op_rendiciones').find(x=>x.id===id);
function rendCalc(x){const gs=C('gastos').filter(g=>g.rendId===x.id&&g.estado!=='Rechazado'&&g.estado!=='Borrador');const tot=gs.reduce((s,g)=>s+(g.moneda===x.moneda?g.monto:(enPEN(g.monto,g.moneda)||0)/(x.moneda==='PEN'?1:(par('tc_'+x.moneda)||1))),0);
 return{gs,tot,saldo:x.anticipo-tot,pend:gs.filter(g=>g.estado==='Enviado').length}}
function gRow(g,showWho){const r=rel(g.relId),cc=get('ccs',g.ccId),mine=g.relId===mrId();
 return `<tr><td class="num">${fd(g.fecha)}</td>${showWho?`<td>${who(g.relId)}</td>`:''}<td><b>${esc(g.categoria)}</b><div class="muted">${esc(g.descripcion||'')}</div></td><td class="num" style="white-space:nowrap"><b>${m2(g.monto,g.moneda)}</b>${g.excede?'<br>'+pill('Excede la política','warn'):''}</td><td>${cc?esc(cc.codigo):'—'}</td><td>${pill(gLab(g),G_EST[g.estado])}${g.rendId?'<br><span class="muted">En rendición</span>':''}</td>
 <td style="text-align:right;white-space:nowrap">${canJefe(g)||canFin(g)?btn('op_gAprobar','Aprobar',{id:g.id},'s p')+' '+btn('op_gRechazar','Rechazar',{id:g.id},'s d'):''}${g.estado==='Aprobado'&&!g.rendId&&can('gastos.pagar')?btn('op_gPagar','Registrar pago',{id:g.id},'s p'):''}${mine&&g.estado==='Borrador'?btn('op_gEnviar','Enviar',{id:g.id},'s p'):''}${mine&&(g.estado==='Borrador'||g.estado==='Rechazado')?' '+btn('op_gEdit',g.estado==='Rechazado'?'Corregir':'Editar',{id:g.id},'s'):''} ${btn('op_gVer','Detalle',{id:g.id},'s')}</td></tr>`}
function vGastos(){const mr=myRel(),all=can('gastos.ver.todos'),ap=gPendMine();
 const tabs=[mr&&can('gastos.registrar')&&['mios','Mis gastos'],(can('gastos.aprobar.jefe')||can('gastos.aprobar.finanzas'))&&['aprob','Por aprobar',ap.length],['rend','Rendiciones y viáticos'],all&&['todos','Todos los gastos'],all&&['cc','Por centro de costo'],(all||can('gastos.politicas'))&&['pol','Políticas']].filter(Boolean);
 const tab=pickTab('op_gTab',tabs);let b='';
 if(tab==='mios'){const gs=C('gastos').filter(g=>g.relId===mr.id).sort((a,b)=>b.fecha.localeCompare(a.fecha));const s=e=>gs.filter(g=>g.estado===e).length;
  b=`<div class="kpis" style="border:0;border-bottom:1px solid var(--line);border-radius:0">${kpi(s('Borrador'),'Borradores')}${kpi(s('Enviado'),'En aprobación')}${kpi(s('Aprobado'),'Aprobados por pagar')}${kpi(s('Rechazado'),'Rechazados',s('Rechazado')?'crit':'')}</div>
  ${gs.length?tbl(['Fecha','Gasto','Monto','C. costo','Estado',''],gs.map(g=>gRow(g))):emptyState('Aún no registras gastos','Registra el gasto con su comprobante; pasará a tu jefe y luego a Finanzas.',btn('op_gNew','Registrar gasto',{},'p'))}`}
 if(tab==='aprob')b=ap.length?`<div class="pb"><div class="note">Revisa el comprobante y la política antes de aprobar. Si rechazas, el motivo llega al colaborador para que corrija.</div></div>`+tbl(['Fecha','Colaborador','Gasto','Monto','C. costo','Estado',''],ap.map(g=>gRow(g,true))):emptyState('Nada por aprobar','Cuando alguien de tu equipo envíe un gasto, o llegue uno a Finanzas, aparecerá aquí.');
 if(tab==='rend'){const rs=C('op_rendiciones').filter(x=>all||x.relId===mrId()||(mr&&rel(x.relId)&&under(rel(x.relId),[mr.id]))).filter(x=>inEmp(relEmp(x.relId)));
  b=rs.length?`<div class="pb grid g2">${rs.map(x=>{const c=rendCalc(x),pct=x.anticipo?Math.min(100,c.tot/x.anticipo*100):0;
   return `<div class="op_card"><div class="row" style="justify-content:space-between"><b>${esc(x.motivo)}</b>${pill(x.estado,{Solicitada:'warn',Abierta:'acc',Cerrada:'ok',Rechazada:'crit'}[x.estado])}</div><div class="muted">${rn(x.relId)} · ${esc(x.destino)} · ${fd(x.desde)} al ${fd(x.hasta)}</div>
   <div class="row" style="justify-content:space-between"><span>Anticipo <b class="num">${m2(x.anticipo,x.moneda)}</b></span><span>Rendido <b class="num">${m2(c.tot,x.moneda)}</b></span></div><div class="bar"><i style="width:${pct}%"></i></div>
   <div>${x.estado==='Cerrada'?`Saldo liquidado: <b>${esc(x.cierre.txt)}</b>`:x.estado==='Solicitada'?'<span class="muted">Esperando que Finanzas entregue el anticipo.</span>':c.saldo>=0?`Por devolver a la empresa: <b class="num">${m2(c.saldo,x.moneda)}</b>`:`A favor del colaborador: <b class="num">${m2(-c.saldo,x.moneda)}</b>`}</div>
   <div class="row">${btn('op_rendVer','Ver gastos ('+c.gs.length+')',{id:x.id},'s')}${x.estado==='Abierta'&&x.relId===mrId()?btn('op_gNew','Agregar gasto',{rend:x.id},'s p'):''}${x.estado==='Solicitada'&&can('gastos.pagar')&&x.relId!==mrId()?btn('op_rendEntregar','Entregar anticipo',{id:x.id},'s p')+btn('op_rendRech','Rechazar',{id:x.id},'s d'):''}${x.estado==='Abierta'&&can('gastos.pagar')&&x.relId!==mrId()?btn('op_rendCerrar','Cerrar rendición',{id:x.id},'s'):''}</div></div>`}).join('')}</div>`
  :emptyState('Sin rendiciones','Solicita un anticipo para un viaje o actividad; luego rinde los gastos contra él y el sistema calcula el saldo.',mr&&can('gastos.registrar')?btn('op_rendNew','Solicitar anticipo',{},'p'):'')}
 if(tab==='todos'){const meses=[...new Set(C('gastos').map(g=>g.fecha.slice(0,7)))].sort().reverse();
  const gs=C('gastos').filter(g=>g.estado!=='Borrador'&&inEmp(relEmp(g.relId))&&(!ui.op_gEst||g.estado===ui.op_gEst)&&(!ui.op_gMes||g.fecha.startsWith(ui.op_gMes))).sort((a,b)=>b.fecha.localeCompare(a.fecha));
  b=`<div class="ph"><div class="row">${fsel('op_gEst',['Enviado','Aprobado','Rechazado','Pagado'],'Todos los estados')}${fsel('op_gMes',meses,'Todos los meses')}</div><span class="muted num">${gs.length} gastos</span></div>${gs.length?tbl(['Fecha','Colaborador','Gasto','Monto','C. costo','Estado',''],gs.map(g=>gRow(g,true))):emptyState('Sin gastos con esos filtros','Cambia el estado o el mes para ver otros gastos.')}`}
 if(tab==='cc'){const meses=[...new Set(C('gastos').map(g=>g.fecha.slice(0,7)))].sort().reverse();
  const gs=C('gastos').filter(g=>['Enviado','Aprobado','Pagado'].includes(g.estado)&&inEmp(relEmp(g.relId))&&(!ui.op_gMes||g.fecha.startsWith(ui.op_gMes)));
  const by={};gs.forEach(g=>{const k=g.ccId||'';by[k]=by[k]||{n:0,tot:0,pag:0,pen:0,cat:{}};const v=enPEN(g.monto,g.moneda)||0;by[k].n++;by[k].tot+=v;if(g.estado==='Pagado')by[k].pag+=v;else by[k].pen+=v;by[k].cat[g.categoria]=(by[k].cat[g.categoria]||0)+v});
  const mx=Math.max(1,...Object.values(by).map(x=>x.tot)),ks=Object.keys(by).sort((a,b)=>by[b].tot-by[a].tot);
  b=`<div class="ph"><div class="row">${fsel('op_gMes',meses,'Todos los meses')}</div><div class="row"><span class="muted">Montos en soles; otras monedas al tipo de cambio de referencia.</span>${can('datos.exportar')?btn('op_gCsv','Exportar',{},'s'):''}</div></div>
  ${ks.length?tbl(['Centro de costo','Gastos','Total','Pagado','En curso','Mayor categoría',''],ks.map(k=>{const c=get('ccs',k),x=by[k],top=Object.entries(x.cat).sort((a,b)=>b[1]-a[1])[0];return `<tr><td><b>${c?esc(c.codigo+' · '+c.nombre):'Sin centro de costo'}</b></td><td class="num">${x.n}</td><td class="num"><b>${m2(x.tot)}</b></td><td class="num">${m2(x.pag)}</td><td class="num">${m2(x.pen)}</td><td>${esc(top[0])}</td><td style="min-width:120px"><div class="bar"><i style="width:${x.tot/mx*100}%"></i></div></td></tr>`})):emptyState('Sin gastos en el periodo','Elige otro mes para ver el reporte.')}`}
 if(tab==='pol'){const ed=can('gastos.politicas'),gp=P().gPol||{};
  b=`<div class="pb"><div class="note">Tope <b>por gasto</b>, en soles, según el nivel del puesto. Al exceder, el sistema avisa, exige justificación y marca el gasto para quien aprueba. «No permitido» = tope cero.</div></div>
  ${tbl(['Categoría',...Object.values(GL),''],G_CAT.map(c=>`<tr><td><b>${c}</b></td>${Object.keys(GL).map(g=>`<td class="num">${gp[c]&&gp[c][g]>0?m2(gp[c][g]):gp[c]&&gp[c][g]===0?'<span class="muted">No permitido</span>':'<span class="muted">Sin tope</span>'}</td>`).join('')}<td style="text-align:right">${ed?btn('op_gPol','Editar',{c},'s'):''}</td></tr>`))}</div>${paramsPanel('gastos',ed,'Tipos de cambio de referencia')}<div hidden>`}
 return pageHead('Operaciones','Gastos y reembolsos',(mr&&can('gastos.registrar')?btn('op_rendNew','Solicitar anticipo')+btn('op_gNew','Registrar gasto',{},'p'):''),'Gastos con comprobante, políticas por nivel de puesto y rendición de viáticos.')+`<div class="panel">${tabsH('op_gTab',tabs)}${b}</div>`}
function gNote(r,cat,monto,mon){if(!cat)return 'Elige la categoría para ver el tope de la política.';const t=tope(r,cat),lv=GL[nivelG(r)];
 return (t==null?'Esta categoría no tiene tope para tu nivel.':t===0?`<b>${esc(cat)}</b> no está permitido para tu nivel (${lv}).`:`Tope por gasto para tu nivel (${lv}) en ${esc(cat)}: <b>${m2(t)}</b>.`)+(Number(monto)>0&&excede(r,cat,monto,mon)?' <b>Este gasto excede la política:</b> debes justificarlo y quien aprueba lo verá marcado.':'')}
const gLive=e=>{const n=document.getElementById('op_gNote');if(!n||!/^f_(categoria|monto|moneda)$/.test(e.target.id||''))return;const mr=myRel(),v=k=>(document.getElementById('f_'+k)||{}).value;if(mr)n.innerHTML=gNote(mr,v('categoria'),v('monto'),v('moneda'))};
document.addEventListener('input',gLive);document.addEventListener('change',gLive);
function gastoForm(id,rendId){const mr=myRel();if(!mr||!can('gastos.registrar'))return toast('Tu usuario no tiene una ficha activa para registrar gastos');const g=id?gas(id):null;
 const rends=C('op_rendiciones').filter(x=>x.relId===mr.id&&x.estado==='Abierta').map(x=>[x.id,x.motivo]);
 openForm(v=>{
  return{title:g?'Editar gasto':'Registrar gasto',ok:'Guardar',
  note:(g&&g.estado==='Rechazado'?`<b>Rechazado:</b> ${esc(g.motivoRechazo)}. Corrige y vuelve a enviar.<br>`:'')+`<span id="op_gNote">${gNote(mr,v.categoria,v.monto,v.moneda)}</span>`,
  fields:[{k:'fecha',l:'Fecha del gasto',type:'date',req:1},{k:'categoria',l:'Categoría',opts:G_CAT,req:1},{k:'monto',l:'Monto',type:'number',req:1},{k:'moneda',l:'Moneda',opts:['PEN','USD','COP'],req:1,keep:1},{k:'ccId',l:'Centro de costo',opts:opt('ccs'),req:1},{k:'tipoComp',l:'Tipo de comprobante',opts:['Factura','Boleta de venta','Recibo por honorarios','Boleto de viaje','Planilla de movilidad'],req:1,keep:1},{k:'nroComp',l:'N.º de comprobante',req:1},{k:'comprobante',l:'Comprobante adjunto (nombre del archivo)',req:1},
   ...(rends.length?[{k:'rendId',l:'Rendición de anticipo (opcional)',opts:rends}]:[]),{k:'descripcion',l:'Descripción',req:1,full:1},{k:'justif',l:'Justificación (obligatoria si excede la política)',type:'textarea',full:1},{k:'accion',l:'Al guardar',opts:[['enviar','Enviar a aprobación'],['borrador','Guardar como borrador']],req:1,keep:1}],
  submit:o=>{if(!(Number(o.monto)>0))return 'El monto debe ser mayor a cero.';if(o.fecha>TODAY)return 'La fecha del gasto no puede ser futura.';if(!/\.(pdf|jpg|jpeg|png|xml)$/i.test(o.comprobante))return 'El comprobante debe ser un archivo PDF, JPG, PNG o XML (por ejemplo: factura-123.pdf).';
   const e=excede(mr,o.categoria,o.monto,o.moneda),x=g||{id:nid('ga'),relId:mr.id,hist:[]};if(e&&!o.justif)return 'Este gasto excede la política: escribe la justificación del exceso.';
   Object.assign(x,{fecha:o.fecha,categoria:o.categoria,monto:Number(o.monto),moneda:o.moneda,ccId:o.ccId,tipoComp:o.tipoComp,nroComp:o.nroComp,comprobante:o.comprobante,rendId:o.rendId||'',descripcion:o.descripcion,excede:e,justif:e?o.justif:'',motivoRechazo:'',estado:'Borrador',etapa:''});
   if(!g){C('gastos').push(x);gHist(x,'Gasto registrado')}else gHist(x,'Gasto corregido');
   log(g?'Edición':'Alta','Gasto',o.categoria+' · '+m2(x.monto,x.moneda),x.id,'',e?'Excede la política':'Dentro de la política');
   if(o.accion==='enviar')enviarGasto(x);else toast('Borrador guardado')}}},g?{...g,accion:'enviar'}:{fecha:TODAY,moneda:cur(mr),ccId:mr.ccId,tipoComp:'Factura',rendId:rendId||'',accion:'enviar'})}
function enviarGasto(g){const r=rel(g.relId),j=r.jefeId&&rel(r.jefeId);g.estado='Enviado';g.etapa=j&&j.estado==='Activo'?'Jefe':'Finanzas';gHist(g,'Enviado a aprobación de '+(g.etapa==='Jefe'?relName(r.jefeId):'Finanzas'));log('Envío a aprobación','Gasto',g.categoria+' · '+m2(g.monto,g.moneda),g.id,'Borrador','Enviado');emit('expense.submitted',{gasto:g});toast('Gasto enviado a '+(g.etapa==='Jefe'?'tu jefe':'Finanzas'))}
function aprobarGasto(g){if(canJefe(g)){g.etapa='Finanzas';gHist(g,'Aprobado por el jefe; pasa a Finanzas');log('Aprobación del jefe','Gasto',relName(g.relId)+' · '+m2(g.monto,g.moneda),g.id,'Por aprobar: jefe','Por aprobar: finanzas');toast('Aprobado: pasa a Finanzas');return true}
 if(canFin(g)){g.estado='Aprobado';g.etapa='';gHist(g,'Aprobado por Finanzas');log('Aprobación de Finanzas','Gasto',relName(g.relId)+' · '+m2(g.monto,g.moneda),g.id,'Por aprobar: finanzas','Aprobado');emit('expense.approved',{gasto:g});toast(g.rendId?'Aprobado: se liquidará al cerrar la rendición':'Aprobado: listo para pagar');return true}
 toast('No te corresponde aprobar este gasto');return false}
