 op_rendEntregar:d=>{const x=rendOf(d.id);if(!x||!can('gastos.pagar'))return;confirmBox('Entregar anticipo',`Se registra la entrega de <b>${m2(x.anticipo,x.moneda)}</b> a ${rn(x.relId)} para «${esc(x.motivo)}». La transferencia real se hace fuera del sistema.`,'Registrar entrega',()=>{x.estado='Abierta';x.entregado=TODAY;log('Entrega de anticipo','Rendición',x.motivo,x.id,'Solicitada','Abierta · '+m2(x.anticipo,x.moneda));toast('Anticipo entregado')})},
