 op_rendCerrar:d=>{const x=rendOf(d.id);if(!x||!can('gastos.pagar'))return;const c=rendCalc(x);if(c.pend)return openModal('No se puede cerrar todavía',`Hay <b>${c.pend}</b> gasto(s) de esta rendición esperando aprobación. Apruébalos o recházalos antes de cerrar.`);
  const txt=c.saldo>0?'El colaborador devuelve '+m2(c.saldo,x.moneda):c.saldo<0?'Se reembolsa al colaborador '+m2(-c.saldo,x.moneda):'Sin saldo: rendición exacta';
  confirmBox('Cerrar rendición',`Anticipo: <b>${m2(x.anticipo,x.moneda)}</b><br>Gastos aprobados: <b>${m2(c.tot,x.moneda)}</b><br><br><b>${txt}.</b><br><span class="muted">Los gastos aprobados quedarán como pagados (liquidados contra el anticipo).</span>`,'Cerrar rendición',()=>{c.gs.filter(g=>g.estado==='Aprobado').forEach(g=>{g.estado='Pagado';g.pago={fecha:TODAY,medio:'Liquidado contra anticipo',ref:x.id};gHist(g,'Liquidado contra el anticipo')});x.estado='Cerrada';x.cierre={fecha:TODAY,saldo:c.saldo,txt,por:me().nombre};log('Cierre de rendición','Rendición',x.motivo,x.id,'Abierta','Cerrada · '+txt);toast('Rendición cerrada')})},
 op_rendVer:d=>{const x=rendOf(d.id);if(!x)return;const c=rendCalc(x),gs=C('gastos').filter(g=>g.rendId===x.id);openModal('Rendición · '+x.motivo,`<dl style="margin-bottom:16px">${dd('Colaborador',rn(x.relId))}${dd('Destino',esc(x.destino))}${dd('Fechas',fd(x.desde)+' al '+fd(x.hasta))}${dd('Anticipo',m2(x.anticipo,x.moneda))}${dd('Rendido',m2(c.tot,x.moneda))}${dd(c.saldo>=0?'Por devolver':'A favor del colaborador',m2(Math.abs(c.saldo),x.moneda))}</dl>${gs.length?tbl(['Fecha','Categoría','Comprobante','Monto','Estado'],gs.map(g=>`<tr><td class="num">${fd(g.fecha)}</td><td>${esc(g.categoria)}<div class="muted">${esc(g.descripcion)}</div></td><td class="mono">${esc(g.comprobante)}</td><td class="num">${m2(g.monto,g.moneda)}</td><td>${pill(gLab(g),G_EST[g.estado])}</td></tr>`)):'<p class="muted">Aún no se han rendido gastos contra este anticipo.</p>'}`,null,true)}
