 t.op_cfg.gPol={'Alimentación':{g1:150,g2:90,g3:60,g4:45},'Hospedaje':{g1:450,g2:300,g3:220,g4:180},'Transporte':{g1:1200,g2:800,g3:600,g4:400},'Movilidad local':{g1:120,g2:80,g3:60,g4:40},'Combustible':{g1:300,g2:250,g3:200,g4:150},'Representación':{g1:600,g2:300,g3:0,g4:0},'Capacitación':{g1:2000,g2:1500,g3:1000,g4:500},'Otros':{g1:300,g2:200,g3:150,g4:100}};
