   fields:[{k:'modo',l:'¿Cómo quieres presentarla?',opts:[['anon','Anónima'],['id','Identificada (con mi nombre)']],req:1,keep:1,dyn:1},{k:'tipo',l:'Tipo',opts:DN_TIPOS,req:1,dyn:1},{k:'empresaId',l:'Empresa donde ocurrió',opts:opt('empresas')},{k:'fechaHechos',l:'Fecha aproximada de los hechos',type:'date'},{k:'lugar',l:'Lugar'},{k:'involucrados',l:'Personas señaladas (nombres o cargos)'},{k:'testigos',l:'Testigos (opcional)'},{k:'descripcion',l:'Qué ocurrió',type:'textarea',req:1,full:1},{k:'evidencia',l:'Evidencia: nombres de archivos, separados por coma (opcional)',full:1}],
