function vDisc(){const full=can('disciplina.ver'),mine=dcMine();if(!full&&!mine.length)return noAccess();
 const sc=scoped().map(r=>r.id),rs=(full?C('op_disc').filter(x=>sc.includes(x.relId)&&inEmp(relEmp(x.relId))):mine).slice().sort((a,b)=>b.fecha.localeCompare(a.fecha));
 return pageHead('Cumplimiento',full?'Casos disciplinarios':'Mis procesos disciplinarios',can('disciplina.gestionar')?btn('op_dcNew','Abrir caso',{},'p'):'',full?'Información confidencial. Toda medida la decide y registra una persona; el sistema nunca la aplica solo.':'Aquí puedes ver los hechos que se te imputan y presentar tus descargos dentro del plazo.')+
 `<div class="panel">${rs.length?tbl(['Fecha','Colaborador','Falta','Descargos','Medida','Estado'],rs.map(x=>`<tr class="click" data-a="op_dcOpen" data-id="${x.id}"><td class="num">${fd(x.fecha)}</td><td>${who(x.relId)}</td><td><b>${esc(x.tipoFalta)}</b><div class="muted">${esc(x.incidente.slice(0,60))}${x.incidente.length>60?'…':''}</div></td><td>${x.descargo?pill('Presentados','ok'):x.estado==='En descargos'?vp(x.descPlazo,2):x.estado==='Abierto'?'<span class="muted">Sin notificar</span>':pill('No presentó','warn')}</td><td>${x.medida?esc(x.medida.tipo):'—'}</td><td>${pill(x.estado,DC_EST[x.estado])}</td></tr>`)):emptyState('Sin casos disciplinarios','Abre un caso para documentar un incidente, pedir descargos y registrar la decisión.',can('disciplina.gestionar')?btn('op_dcNew','Abrir caso',{},'p'):'')}</div>`}
function vDiscDet(){const x=dcase(ui.op_discId),full=can('disciplina.ver')&&x&&scoped().some(r=>r.id===x.relId),mine=x&&x.relId===mrId()&&x.estado!=='Abierto';
 if(!x||!(full||mine))return noAccess('Caso confidencial','No tienes acceso a este caso disciplinario.');const ges=full&&can('disciplina.gestionar'),dec=full&&can('disciplina.decidir');
 return `<div class="crumb"><a href="#" data-a="nav" data-r="op_disc">${full?'Casos disciplinarios':'Mis procesos disciplinarios'}</a> / ${rn(x.relId)}</div>
 <div class="panel"><div class="pb"><div class="row" style="justify-content:space-between;align-items:flex-start"><div><h1>${esc(x.tipoFalta)}</h1><div class="row" style="margin-top:6px">${pill(x.estado,DC_EST[x.estado])}<span class="muted">${rn(x.relId)} · hechos del ${fd(x.fecha)}</span></div></div>
 <div class="row">${ges&&x.estado==='Abierto'?btn('op_dcNotif','Notificar y pedir descargos',{},'p'):''}${ges&&x.estado==='En descargos'?btn('op_dcSinDesc','Continuar sin descargos'):''}${dec&&x.estado==='En evaluación'?btn('op_dcDecidir','Registrar decisión',{},'p'):''}${ges&&x.estado==='Decidido'?(x.medida.aplicada||x.medida.tipo==='Sin sanción'?'':btn('op_dcAplicar','Registrar aplicación',{},'p'))+btn('op_dcCerrar','Cerrar caso'):''}${ges&&x.estado!=='Cerrado'?btn('op_dcDoc','Adjuntar documento')+btn('op_dcSeg','Agregar seguimiento'):''}${mine&&x.estado==='En descargos'&&!x.descargo?btn('op_dcDescargo','Presentar descargos',{},'p'):''}</div></div></div>
 <div class="pb" style="border-top:1px solid var(--line)"><h3 style="margin-bottom:8px">Hechos imputados</h3><p>${esc(x.incidente)}</p><dl style="margin-top:14px">${dd('Fecha de los hechos',fd(x.fecha))}${dd('Abierto por',esc(x.abiertoPor))}${dd('Plazo de descargos',x.descPlazo?fd(x.descPlazo)+(x.estado==='En descargos'?' '+vp(x.descPlazo,2):''):'Aún no notificado')}${dd('Documentos',fileChips(x.docs))}</dl></div></div>
 <div class="grid g2"><div class="panel"><div class="ph"><h2>Descargos del colaborador</h2>${x.descargo?pill('Presentados','ok'):''}</div><div class="pb">${x.descargo?`<p>${esc(x.descargo.texto)}</p><div class="muted" style="margin-top:8px">Presentados el ${fd(x.descargo.fecha)}${x.descargo.archivo?' · '+esc(x.descargo.archivo):''}</div>`:x.estado==='Abierto'?'<span class="muted">El colaborador aún no ha sido notificado.</span>':x.estado==='En descargos'?`<span class="muted">Dentro del plazo. ${mine?'Presenta tus descargos antes del '+fd(x.descPlazo)+'.':'El colaborador puede presentarlos desde su cuenta hasta el '+fd(x.descPlazo)+'.'}</span>`:'<span class="muted">No se presentaron descargos dentro del plazo.</span>'}</div></div>
 <div class="panel"><div class="ph"><h2>Decisión</h2>${x.medida?pill(x.medida.tipo,x.medida.tipo==='Sin sanción'?'ok':'warn'):''}</div><div class="pb">${x.medida?`<dl>${dd('Medida',esc(x.medida.tipo)+(x.medida.dias?' · '+x.medida.dias+' días':''))}${dd('Decidió',esc(x.medida.por))}${dd('Fecha',fd(x.medida.fecha))}${dd('Aplicación',x.medida.tipo==='Sin sanción'?'No corresponde':x.medida.aplicada?'Aplicada el '+fd(x.medida.aplicada):'<span class="pill warn">Pendiente de aplicar por RRHH</span>')}</dl><p style="margin-top:12px"><b>Fundamento:</b> ${esc(x.medida.fundamento)}</p>`:'<span class="muted">Aún sin decisión. La registra una persona con el permiso «Decidir medidas disciplinarias», después de evaluar los descargos.</span>'}</div></div></div>
 ${full?`<div class="panel"><div class="ph"><h2>Seguimiento</h2></div><div class="pb"><ul class="tl">${x.seg.map(s=>`<li><b>${esc(s.t)}</b><div class="muted">${fd(s.f)} · ${esc(s.u)}</div></li>`).join('')}</ul></div></div>`:''}`}
Object.assign(ACT,{
 op_dcOpen:d=>{const x=dcase(d.id);if(x&&can('disciplina.ver'))log('Consulta','Caso disciplinario',relName(x.relId),x.id,'','Apertura del caso',true);save();go('op_discDet',{op_discId:d.id})},
 op_dcNew:()=>{if(!can('disciplina.gestionar'))return;const sc=scoped().map(r=>r.id);openForm(()=>({title:'Abrir caso disciplinario',ok:'Abrir caso',note:'El caso se abre sin notificar. Cuando esté documentado, usa «Notificar y pedir descargos».',fields:[{k:'relId',l:'Colaborador',opts:actRels(r=>sc.includes(r.id)),req:1},{k:'fecha',l:'Fecha de los hechos',type:'date',req:1},{k:'tipoFalta',l:'Tipo de falta',opts:['Tardanzas o inasistencias','Incumplimiento de funciones','Incumplimiento de normas de seguridad','Conducta inapropiada','Uso indebido de recursos','Falta grave','Otra'],req:1},{k:'incidente',l:'Descripción de los hechos',type:'textarea',req:1,full:1},{k:'docs',l:'Documentos de sustento: nombres de archivos, separados por coma',full:1}],
  submit:o=>{if(o.fecha>TODAY)return 'La fecha de los hechos no puede ser futura.';const x={id:nid('dc'),relId:o.relId,fecha:o.fecha,tipoFalta:o.tipoFalta,incidente:o.incidente,docs:files(o.docs),estado:'Abierto',descPlazo:'',descargo:null,medida:null,seg:[],abiertoPor:me().nombre};dcSeg(x,'Caso abierto');C('op_disc').push(x);log('Apertura','Caso disciplinario',relName(o.relId),x.id,'',o.tipoFalta,true);ui.op_discId=x.id;ui.route='op_discDet';toast('Caso abierto')}}),{fecha:TODAY})},
 op_dcNotif:()=>{const x=dcase(ui.op_discId);if(!x||!can('disciplina.gestionar'))return;openForm(()=>({title:'Notificar y pedir descargos',ok:'Notificar',note:`El colaborador verá los hechos en su cuenta y podrá presentar descargos. Plazo de referencia: <b>${par('disc_descargo')} días</b>${confTag('disc_descargo')}. La carta se entrega también por el medio formal de la empresa.`,fields:[{k:'plazo',l:'Fecha límite para descargos',type:'date',req:1}],submit:o=>{if(o.plazo<=TODAY)return 'El plazo debe ser posterior a hoy.';x.estado='En descargos';x.descPlazo=o.plazo;dcSeg(x,'Notificado. Descargos hasta el '+fd(o.plazo));log('Notificación','Caso disciplinario',relName(x.relId),x.id,'Abierto','En descargos hasta '+fd(o.plazo),true);toast('Colaborador notificado')}}),{plazo:D(par('disc_descargo'))})},
 op_dcDescargo:()=>{const x=dcase(ui.op_discId);if(!x||x.relId!==mrId()||x.estado!=='En descargos')return;openForm(()=>({title:'Presentar descargos',ok:'Presentar',note:'Explica tu versión de los hechos. Una vez presentados no se pueden modificar.',fields:[{k:'texto',l:'Descargos',type:'textarea',req:1,full:1},{k:'archivo',l:'Documento adjunto (nombre del archivo, opcional)'}],submit:o=>{x.descargo={fecha:TODAY,texto:o.texto,archivo:o.archivo};x.estado='En evaluación';dcSeg(x,'Descargos presentados por el colaborador');log('Descargos presentados','Caso disciplinario',relName(x.relId),x.id,'En descargos','En evaluación',true);toast('Descargos presentados')}}),{})},
 op_dcSinDesc:()=>{const x=dcase(ui.op_discId);if(!x||!can('disciplina.gestionar'))return;if(x.descPlazo>=TODAY)return openModal('El plazo sigue abierto',`El colaborador puede presentar descargos hasta el <b>${fd(x.descPlazo)}</b>. No se puede continuar sin descargos antes de esa fecha.`);confirmBox('Continuar sin descargos','El plazo venció sin descargos. El caso pasará a evaluación.','Continuar',()=>{x.estado='En evaluación';dcSeg(x,'Plazo vencido sin descargos');log('Sin descargos','Caso disciplinario',relName(x.relId),x.id,'En descargos','En evaluación',true)})},
 op_dcDecidir:()=>{const x=dcase(ui.op_discId);if(!x||!can('disciplina.decidir')||x.estado!=='En evaluación')return;openForm(v=>({title:'Registrar decisión',ok:'Registrar decisión',note:'La decisión es de una persona y queda con su nombre. <b>El sistema no aplica la medida:</b> Recursos Humanos la ejecuta y registra su aplicación.'+(x.descargo?'':' El colaborador no presentó descargos.'),fields:[{k:'tipo',l:'Medida',opts:['Sin sanción','Amonestación verbal','Amonestación escrita','Suspensión sin goce de haber','Otra'],req:1,dyn:1},...(v.tipo==='Suspensión sin goce de haber'?[{k:'dias',l:'Días de suspensión',type:'number',req:1}]:[]),{k:'fundamento',l:'Fundamento de la decisión',type:'textarea',req:1,full:1}],
  submit:o=>{if(o.tipo==='Suspensión sin goce de haber'&&!(Number(o.dias)>0))return 'Indica los días de suspensión.';x.medida={tipo:o.tipo,dias:o.tipo==='Suspensión sin goce de haber'?Number(o.dias):0,fundamento:o.fundamento,fecha:TODAY,por:me().nombre,aplicada:''};x.estado='Decidido';dcSeg(x,'Decisión registrada: '+o.tipo);log('Decisión disciplinaria','Caso disciplinario',relName(x.relId),x.id,'En evaluación',o.tipo,true);toast('Decisión registrada')}}),{})},
 op_dcAplicar:()=>{const x=dcase(ui.op_discId);if(!x||!can('disciplina.gestionar')||!x.medida)return;openForm(()=>({title:'Registrar aplicación de la medida',note:`<b>${esc(x.medida.tipo)}</b>${x.medida.dias?' · '+x.medida.dias+' días':''}. Confirma que la medida ya se comunicó y ejecutó.`,fields:[{k:'fecha',l:'Fecha de aplicación',type:'date',req:1},{k:'doc',l:'Carta o constancia firmada (nombre del archivo)',req:1}],submit:o=>{x.medida.aplicada=o.fecha;x.docs.push(o.doc);dcSeg(x,'Medida aplicada el '+fd(o.fecha));log('Aplicación de medida','Caso disciplinario',relName(x.relId),x.id,'Pendiente','Aplicada',true);emit('discipline.applied',{rel:rel(x.relId),caso:x});toast('Aplicación registrada')}}),{fecha:TODAY})},
 op_dcCerrar:()=>{const x=dcase(ui.op_discId);if(!x||!can('disciplina.gestionar'))return;if(x.medida&&x.medida.tipo!=='Sin sanción'&&!x.medida.aplicada)return openModal('Falta registrar la aplicación','La medida decidida aún no figura como aplicada. Registra su aplicación antes de cerrar el caso.');confirmBox('Cerrar caso','El caso quedará cerrado y archivado en el legajo confidencial.','Cerrar caso',()=>{x.estado='Cerrado';dcSeg(x,'Caso cerrado');log('Cierre','Caso disciplinario',relName(x.relId),x.id,'Decidido','Cerrado',true)})},
 op_dcDoc:()=>{const x=dcase(ui.op_discId);if(!x||!can('disciplina.gestionar'))return;openForm(()=>({title:'Adjuntar documento',fields:[{k:'n',l:'Nombre del archivo',req:1,full:1}],submit:o=>{x.docs.push(o.n);dcSeg(x,'Documento adjuntado: '+o.n);log('Documento','Caso disciplinario',relName(x.relId),x.id,'',o.n,true)}}),{})},
 op_dcSeg:()=>{const x=dcase(ui.op_discId);if(!x||!can('disciplina.gestionar'))return;openForm(()=>({title:'Agregar seguimiento',fields:[{k:'t',l:'Nota de seguimiento',type:'textarea',req:1,full:1}],submit:o=>{dcSeg(x,o.t);log('Seguimiento','Caso disciplinario',relName(x.relId),x.id,'','Nota agregada',true)}}),{})}
});
