function expBuild(x){const t=T(),meses=[];let m=x.desde;while(m<=x.hasta&&meses.length<36){meses.push(m);const d=new Date(m+'-15');d.setMonth(d.getMonth()+1);m=iso(d).slice(0,7)}
 const d0=x.desde+'-01',d1=x.hasta+'-31',pers=(t.nomPeriodos||[]).filter(p=>p.empresaId===x.empresaId&&meses.includes(p.periodo));
 return x.relIds.map(id=>{const r=rel(id);if(!r)return null;const it=[];const add=(sec,ok,txt)=>it.push({sec,ok,txt});
  const docs=(t.documentos||[]).filter(dc=>dc.relId===id),ct=docs.find(dc=>/contrato/i.test((dc.carpeta||'')+' '+(dc.nombre||'')));
  add('Contrato',ct?(ct.estadoFirma==='Pendiente'?'par':'ok'):'par',ct?`${ct.nombre} (${ct.estadoFirma||'archivado'})`:`Contrato ${r.contratoTipo.toLowerCase()} registrado en la ficha${r.contratoFin?' hasta el '+fd(r.contratoFin):''}; falta el documento firmado en el legajo digital.`);
  const bol=(t.nomBoletas||[]).filter(b=>b.relId===id&&pers.some(p=>p.id===b.periodoId)),mf=meses.filter(mm=>!pers.some(p=>p.periodo===mm&&bol.some(b=>b.periodoId===p.id)));
  add('Boletas de pago',!mf.length?'ok':bol.length?'par':'no',bol.length?`${bol.length} de ${meses.length} boletas${mf.length?'. Faltan: '+mf.join(', '):''}`:`Sin boletas en el sistema para ${meses.length} periodo(s).`);
  const mk=(t.marcaciones||[]).filter(a=>a.relId===id&&a.fecha>=d0&&a.fecha<=d1);add('Registro de asistencia',mk.length?'ok':'no',mk.length?`${mk.length} marcaciones en el periodo.`:'Sin marcaciones en el sistema para el periodo.');
  const vc=(t.vacSolicitudes||[]).filter(v=>v.relId===id&&v.estado==='Aprobada'&&v.desde<=d1&&v.hasta>=d0);add('Vacaciones',vc.length?'ok':'par',vc.length?`${vc.length} descanso(s) aprobado(s): ${vc.reduce((s,v)=>s+(v.dias||0),0)} días.`:'Sin descansos vacacionales aprobados en el periodo.');
  const em=C('op_sstEmo').filter(e=>!e.anulado&&e.relId===id).sort((a,b)=>b.fecha.localeCompare(a.fecha))[0];add('SST · Examen médico ocupacional',em?(em.vence>=TODAY?'ok':'par'):'no',em?`${em.tipo} del ${fd(em.fecha)}: ${em.aptitud}; ${em.vence>=TODAY?'vigente hasta':'venció el'} ${fd(em.vence)}.`:'Sin examen médico ocupacional registrado.');
  const cp=C('op_sstCapac').filter(c=>!c.anulado&&(c.asistentes||[]).includes(id)&&c.fecha>=d0&&c.fecha<=d1);add('SST · Capacitaciones',cp.length?'ok':'no',cp.length?cp.map(c=>c.tema).join('; '):'Sin asistencia a capacitaciones de SST en el periodo.');
  const ep=C('op_eppEntregas').filter(e=>!e.anulado&&e.relId===id),sf=ep.filter(e=>e.estado!=='Firmado').length;const rg=r.tipoTrabajador==='Obrero'||(P().sedesRiesgo||[]).includes(r.sedeId);
  add('SST · Entrega de EPP',ep.length?(sf?'par':'ok'):rg?'no':'ok',ep.length?`${ep.length} entrega(s)${sf?', '+sf+' sin cargo firmado':', todas con cargo firmado'}.`:rg?'Puesto de riesgo sin entregas de EPP registradas.':'No corresponde: puesto sin exposición a riesgo.');
  const cn=docs.filter(dc=>/constancia|certificado|vida ley|sctr|cts/i.test((dc.carpeta||'')+' '+(dc.nombre||'')));add('Constancias',cn.length?'ok':'no',cn.length?cn.map(dc=>dc.nombre).join('; '):'Sin constancias (CTS, Vida Ley, SCTR, entrega de boletas) en el legajo digital.');
  return{r,it}}).filter(Boolean)}
